WITH payload AS (SELECT $archive_payload$[{"id":"25760b2f-5f6c-5148-9c91-fce22e8aca8f","document_type":"judgment","category":"judicial","subcategory":"general","title":"إنشاء مخطط عشوائي -دفع شكلي بعدم االختصاص -صرف النظر عن دعوى املدعي العام لعدم االختصاص -املادة الثالثة من نظام اإلجراءات اجلزائية .","document_number":"3448338","case_number":"33710239","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/26","year":"1434","subject":"إنشاء مخطط عشوائي -دفع شكلي بعدم االختصاص -صرف النظر عن دعوى املدعي العام لعدم االختصاص -املادة الثالثة من نظام اإلجراءات اجلزائية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3448338 :‬تاريخه‪1434/02/26 :‬هـ‬\n                         ‫رقم الدعوى‪33710239 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34228267‬تاريخه‪1434/06/03 :‬هـ‬\n\n\n      ‫إنشــاء مخطــط عشــوائي‪ -‬دفــع شــكلي بعــدم االختصــاص ‪ -‬صــرف‬\n                   ‫النظــر عــن دعــوى املدعــي العــام لعــدم االختصــاص‬\n\n\n\n\n                              ‫‪ -‬املادة الثالثة من نظام اإلجراءات اجلزائية ‪.‬‬\n      ‫‪ -‬الئحــة اجلــزاءات والغرامــات عــن مخالفــات البلدية الفقرة (‪)8/4/3‬‬\n      ‫املــادة (‪( : )4‬مينــع البنــاء باألراضــي احلكوميــة غيــر املخططــة بــدون‬\n      ‫احلصــول علــى ترخيــص بنــاء نظامــي ‪ ،‬داخــل أو خــارج املخططــات‬\n                                       ‫الهيكليــة املعتمــدة للمــدن والقــرى‪).‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتوجيــه التهمــة لــه بإنشــاء‬\n      ‫مخطــط عشــوائي ‪ ،‬حيــث ورد خطــاب للجهــة املختصــة عــن قيــام‬\n      ‫املدعــى عليــه بإنشــاء مخطــط عشــوائي يف أحــد الهجــر ‪ ،‬ومت االنتقــال‬\n      ‫للموقــع وشــوهدت أرض كبيــرة وبهــا بعــض الشــوارع املســفلتة ‪،‬‬\n      ‫وأثبتــت التحريــات قيــام املدعــى عليــه بإنشــاء املخطــط ‪ ،‬وهــو ميــارس‬\n      ‫البيــع والشــراء يف األراضــي العشــوائية ويســكن نفــس املنطقــة ‪،‬‬\n      ‫وطلــب املدعــي العــام تعزيــر املدعــى عليــه لقــاء ذلــك ‪ ،‬حضــر املدعــي‬\n      ‫عليــه ووكيلــه وأجــاب عــن الدعــوى املقامــة مــن املدعــي العــام بدفــع‬\n\n‫‪207‬‬\n\f‫شــكلي‪ ،‬املتضمــن عــدم اختصــاص احملكمــة بهــذه الدعــوى‪ ،‬والدفــع‬\n‫املوضوعــي أن املدعــى عليــه ميلــك األرض ملــك ًا صحيح ـ ًا مبوجــب‬\n‫صــك شــرعي ‪ ،‬وأن املدعــى عليــه بــاع األرضــي ‪ ،‬وأصحــاب األراضــي‬\n‫هــم مــن بنــى عليهــا ‪ ،‬حكمــت احملكمــة بصــرف النظــر عــن دعــوى‬\n‫املدعــي العــام ضــد املدعــى عليــه لعــدم اختصــاص احملكمــة بنظــر‬\n‫هــذا النــوع مــن القضايــا ‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬واملدعــي العــام‬\n‫قــرر اعتراضــه علــى احلكــم بالئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪...........‬‬\n‫وتاريــخ ‪1433/12/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ .............‬وتاريــخ‬\n‫‪ 1433/12/28‬ه ـ ففــي يــوم االثنــن املوافــق ‪ 1434/01/26‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 09 : 45‬وفيهــا حضــر املدعــي العــام ســعودي اجلنســية‬\n‫املكلــف برقــم ه ـ م‪ 6057/1/2/‬يف ‪1433/10/16‬ه ـ وادعــى قائــا‬\n‫أدعــي علــى ‪ ، /‬البالــغ مــن العمــر (‪ )50‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي برقــم ‪ ......‬يقيــم مبكــة املكرمــة ومفــرج عنــه‬\n                       ‫بالكفالــة احلضوريــة املرفــق علــى اللفــة رقــم(‪.)31‬‬\n‫باالطــاع علــى خطــاب ســعادة وكيــل أمــارة منطقــة مكــة املكرمــة‬\n‫رقــم ‪ .............‬وتاريــخ ‪1433/9/24‬ه ـ املبنــى علــى خطــاب رئيس مركز‬\n‫‪ ..........‬رقــم ‪ .........‬وتاريــخ ‪1433/8/13‬ه ـ املتضمــن قيــام املدعــى عليــه‬\n\n                                                                                    ‫‪208‬‬\n\f      ‫رفــق شــخصني آخريــن (فصلــت لهمــا أوراق مســتقلة) بإنشــاء مخطــط‬\n      ‫‪ ................‬وباالنتقــال ملوقــع أنشــاء املخطــط بهجــرة رفــق منــدوب‬\n      ‫مركــز ‪ ...........‬شــوهدت أرض مبســاحة كبيــرة وبهــا بعــض الشــوارع‬\n      ‫املســفلتة ‪ ،‬وبتاريــخ ‪1433/11/17‬ه ـ مت القبــض علــى املدعــى عليــه مــن‬\n                                          ‫قبــل أفــراد التحريــات والبحــث اجلنائــي ‪.‬‬\n      ‫وقــد ورد خطــاب شــعبة التحريــات والبحــث اجلنائــي رقــم(‪)517567‬‬\n      ‫وتاريــخ ‪1433/11/17‬ه ـ املتضمــن أن التحريات أثبت قيام املدعى عليه‬\n      ‫بإنشــاء املخطــط وهــو ميــارس البيــع والشــراء يف األراضــي العشــوائية‬\n                                                               ‫ويســكن بنفــس املنطقــة ‪.‬‬\n      ‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بإنشــاء مخطــط‬\n                                          ‫عشــوائي وذلــك لألدلــة والقرائــن اآلتيــة‪ :‬ـ ـ‬\n      ‫‪ .1‬مــا ورد بخطــاب البحــث اجلنائــي املشــار إليــه املرفــق علــى اللفــة‬\n                                                                                   ‫رقــم(‪. )21‬‬\n      ‫‪ .2‬مــا ورد مبحضــر االنتقــال واملعاينــة املنــوه عنــه املــدون علــى الصفحــة‬\n                                                                    ‫رقــم(‪ )11‬لفــه رقــم(‪. )1‬‬\n      ‫‪ .3‬مــا ورد مبحضــر القبــض والتفتيــش املنــوه عنــه املرفــق علــى اللفــة‬\n                                                                                    ‫رقــم(‪. )16‬‬\n                     ‫يعثر له على سوابق مسجلة بحقه ‪.‬‬           ‫وبالبحث عن سوابقه لم ُ‬\n      ‫وحيــث إن مــا قــام بــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا‬\n      ‫أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n      ‫مــا أســند إليــه اســتناد ًا لبرقيــة صاحــب الســمو امللكــي أميــر منطقــة‬\n      ‫مكــة املكرمــة رقــم(‪/626311‬ب س) وتاريــخ ‪1433/5/12‬ه ـ هــذه‬\n      ‫دعــواي وبســؤال املدعــى عليــه عــن الدعــوى طلــب املهلــة لإلجابــة وعليــه‬\n\n\n‫‪209‬‬\n\f‫رفعــت اجللســة يف يــوم الثالثــاء ‪1434/2/5‬ه ـ الســاعة العاشــرة صباحــا‬\n‫وأقفلــت اجللســة الســاعة العاشــرة والنصــف صباحــا وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                          ‫‪ 1434/01/26‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/02/05‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام‬\n‫واملدعــى عليــه ســعودي اجلنســية ســجل رقــم بوكالتــه عــن ســعودي‬\n‫اجلنســية ســجل رقــم بالوكالــة رقــم ‪ 19665‬يف ‪1431/6/16‬ه ـ‬\n‫والصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة والتــي تخولــه‬\n‫املرافعــة واملدافعــة إلــخ وقــدم مذكــرة جوابيــة علــى الدعــوى وهــذا‬\n‫نصهــا وجواب ـ ًا علــى صحيفــة الدعــوى أفيــد فضيلتكــم مبــا يلــي ‪-:‬‬\n‫أو ًال ‪ -:‬الدفــع الشــكلي ‪ .‬مــع عــدم اإلقــرار بصحــة الدعــوى إال أننــا‬\n‫نطلــب مــن احملكمــة املوقــرة احلكــم بصــرف النظــر عــن دعــوى املدعــي‬\n‫العــام لعــدم اختصــاص احملكمــة مبثــل هــذه التهــم ‪ ،‬حيــث جــاء‬\n‫قــرار اإلحالــة الصــادر مــن املدعــي العــام للمحكمــة اجلزئيــة مخالف ـ ًا‬\n‫للنظــام العــام ‪ ،‬حيــث إن البنــاء مــن غيــر تصريــح أحــد املخالفــات‬\n‫املذكــورة يف نظــام البلديــات واملنصــوص عليهــا يف املــادة الرابعــة‬\n‫مــن الئحــة تنظيــم املخالفــات البلديــة الصــادرة بقــرار مجلــس الــوزراء‬\n‫رقــم ‪ 218‬يف ‪1422/8/6‬ه ـ والتــي ُذكــر فيهــا العقوبــة املترتبــة علــى‬\n‫هــذه املخالفــة مبوجــب قــرار مجلــس الــوزراء وليــس منهــا اإلحالــة إلــى‬\n‫احملكمــة اجلزئيــة إلصــدار عقوبــة قضائيــة ‪ ،‬وإن كان هنــاك مخالفــة‬\n‫قــد ارتكبهــا موكلــي ‪ ،‬وهــو مــا لــم ولــن نســلم بــه علــى اإلطــاق ‪،‬‬\n‫فيكــون االختصــاص بتطبيــق عقوبــة املخالفــة عليــه حتــت نظــام الئحــة‬\n\n\n                                                                                 ‫‪210‬‬\n\f      ‫تنظيــم املخالفــات البلديــة واجلهــة املخولــة باملعاقبــة عليــه هــي األمانــة‬\n      ‫وللمتضــرر االعتــراض يف احملكمــة اإلداريــة خــال املــدة النظاميــة ‪.‬‬\n      ‫ثاني ـ ًا ‪ -:‬الدفــع املوضوعــي ‪ .‬مــع متســكنا بالدفــع الشــكلي يف جميــع‬\n      ‫مراحــل احملاكمــة فإننــا نوجــز ردنــا علــى موضــوع الدعــوى فيمــا يلــي ‪-:‬‬\n      ‫ا‬\n      ‫‪ -1‬إن مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح جملـ ًة وتفصيـ ً‬\n      ‫حيــث نســب املدعــي العــام إلــى موكلــي تهمــة إنشــاء مخطــط عشــوائي‬\n      ‫وهــذا غيــر صحيــح ‪ ،‬حيــث إن ركــن التهمــة املنســوبة ملوكلــي هــو‬\n      ‫مزاولــة البنــاء علــى أرض حكوميــة بــدون ترخيــص ‪ ،‬وموكلــي لــم‬\n      ‫يحصــل منــه ذلــك مطلقـ ًا ولــم يباشــر بنفســه أو بواســطة وكيــل عنــه أو‬\n      ‫موظــف تابــع لــه أي أعمــال بنــاء وإنشــاء على اإلطــاق ‪ ،‬وإن كان هناك‬\n      ‫مخالفــات متــت مــن بعــض مــن متلكــوا أراضــي بالشــراء مــن مالكيهــا‬\n      ‫األصليــن فهــم املســئولون عــن أفعالهــم وليــس موكلــي ‪ ،‬ســواء كانــت‬\n      ‫املخالفــات الصــادرة منهــم هــي البنــاء بغيــر تصريــح أو غيــر ذلــك ‪ ،‬إذ ال‬\n                                           ‫دخــل ملوكلــي مبــا قامــوا بــه مــن أفعــال ‪.‬‬\n      ‫‪ -2‬إن مــا يريــد املدعــي العــام جترميــه هــو فعــل طبيعــي بــل ومعتــاد بــن‬\n      ‫الشــركاء ‪ ،‬فلــو افترضنــا أن األرض مملوكــة لثالثــن شــريك ًا ثــم‬\n      ‫قــام هــؤالء الشــركاء بتقاســم هــذه األرض إلــى ثالثــن قطعــة وحــرروا‬\n      ‫محضــر ًا لهــذه القســمة وحــددوا األطــوال واملســاحات واحلــدود املتعلقــة‬\n      ‫مبلكيــة كل واحــد منهــم ‪ ،‬فكيــف يســوغ للمدعــي العــام جتــرمي هــذا‬\n      ‫الفعــل وهــو يحصــل يوميـ ًا يف اململكــة العربيــة الســعودية ‪ ،‬بــل ومــا تــزال‬\n      ‫محاضــر القســمة يحكــم مبقتضاهــا وتفــرز علــى أساســها األراضــي‬\n                       ‫والعقــارات دون إنــكار مــن اجلهــات الشــرعية أو اإلداريــة ‪.‬‬\n      ‫‪ -3‬إن مــا فعلــه موكلــي هــو التصــرف مبلكــه الثابــت لــه بالشــراء مــن‬\n\n\n‫‪211‬‬\n\f‫وقــد كان موكلــي اشــترى هــذه األرض يف ‪1425/1/9‬ه ـ مبوجــب‬\n‫عقــد املبايعــة املــؤرخ يف ‪1425/1/9‬ه ـ واملتضمــن بيــع املذكــور علــى‬\n‫موكلــي قطعــة األرض الواقعــة بــأم شــناق بســمار واحملــدودة شــرق ًا‬\n‫باجلبــال املتصلــة وغربـ ًا الســلك الشــائك وأكــوام التــراب وشــما ًال ملــك‬\n‫راضــي الدعــدي وجنوب ـ ًا بالســكة النافــذة ورثــة حســب الكروكــي‬\n‫مببلــغ مليــون وأربعمائــة ألــف ريــال وأضيــف يف آخــر الورقــة ملحوظــة ‪:‬‬\n‫املبلــغ املدفــوع عنــد كتابــة هــذه املبايعــة أربعمائــة ألــف ريــال والباقــي‬\n‫مليــون ريــال عنــد خــروج الصــك وإفراغــه وقــد ُضبــط كل ذلــك يف صك‬\n‫النــزاع املرفــق ورقمــه ‪ 26/31/111‬يف ‪1430/9/10‬ه ـ ثــم إن موكلــي‬\n‫قــد بــاع العقــار املذكــور علــى ثــم رجــع بعــد ذلــك واشــترى العقــار مــرة‬\n‫وحــل النــزاع الــذي تســبب بــه إيقــاف‬‫أخــرى مببلــغ ســتة ماليــن ريــال ُ‬\n‫الصكــوك مبوجــب األمــر امللكــي وقــد قــام موكلــي بإعــداد مخطــط‬\n‫لــأرض كامــل قســمه فيهــا إلــى قطــع وقــام ببيــع األرض علــى أحــد‬\n‫املســتثمرين وهــو الــذي قــام ببيــع قطــع األراضــي مجزئــة علــى املشــتريني‬\n‫األفــراد لكــي يقومــوا باإلجــراءات النظاميــة اجتــاه أمالكهــم وتقــدمي‬\n‫طلبــات احلجــج لألراضــي حســب النظــام ‪ ،‬وبالفعــل قــام األفــراد (‬\n‫املشــتريني ) باتخــاذ اإلجــراءات الالزمــة وقامــت األمانــة بســفلتة الطــرق‬\n‫وإيصــال اخلدمــات للمشــتريني وقامــت شــركة الكهربــاء بإيصــال‬\n‫التيــار الكهربائــي وكل ذلــك يــدل علــى موافقــة اجلهــات املختصــة‬\n‫ُملــاك األراضــي فيمــا قامــوا بــه ‪ ،‬وهــذا وحــده دليــل كاف علــى أنــه‬\n‫ال توجــد تهمــة أو مخالفــة مــن األســاس حيــث إن جهــة االختصــاص لــم‬\n‫متنــع البنــاء الــذي قــام بــه املشــترون بــل ولــم متتنــع عــن إيصــال اخلدمــات‬\n‫ملســاكنهم ‪ ،‬ولــو كان موكلــي يتصــرف يف غيــر ملكــه أو كان‬\n\n\n                                                                                         ‫‪212‬‬\n\f                      ‫إجــراءه للبيــع غيــر نظامــي ملــا اســتجابت األمانــة للمــاك ‪.‬‬\n      ‫‪ -4‬نــص النظــام األساســي للحكــم علــى قاعــدة شــرعية مســتقرة وهــي‬\n      ‫ال عقوبــة إال بنــص ‪ ، ،‬واملــراد بالنــص هنــا نــص يفيــد التجــرمي ونــص‬\n      ‫يفيــد العقوبــة إمــا بتحديدهــا أو بتركهــا لنظــر القاضــي وكال النصني‬\n      ‫يف قضيتنــا التــي نحــن يف صددهــا معدومــان فــا نــص شــرعي وال نــص‬\n      ‫نظامــي يفيــد بتجــرمي امتــاك األراضــي أو بيعهــا أو بيــع أجــزاء منهــا‬\n      ‫وعلــى فــرض وجــود شــبهة لهــذا النــص يف أنظمــة األمانــة فإنــه ال نــص يف‬\n      ‫العقوبــة بــل أنظمــة األمانــة صريحــة يف العقوبــات مــن جنــس إزالــة البنــاء‬\n      ‫غيــر املرخــص وتغــرمي مــن قــام بالبنــاء علم ـ ًا أن موكلــي لــم يقــم بذلــك‬\n                                                                                 ‫مطلقـ ًا ‪.‬‬\n      ‫وقــد نصــت الالئحــة التنفيذيــة لنظــام اإلجــراءات اجلزائيــة يف مادتهــا‬\n      ‫الثالثــة علــى أنــه ال يجــوز توقيــع عقوبــة جزائيــة علــى أي شــخص إال علــى‬\n      ‫أمــر محظــور ومعاقــب عليــه شــرع ًا أو نظام ـ ًا وبعــد ثبــوت إدانتــه بنــاء‬\n            ‫ت ــرى وفق ـ ًا للوجــه الشــرعي ‪.‬‬‫علــى حكــم ن ــهائي بعــد محاكمــة ُ ْ‬\n      ‫وحيــث إنــه لــم يصــدر مــن موكلــي أي فعــل مخالــف أو معاقــب عليــه‬\n      ‫شــرع ًا أو نظام ـ ًا فإنــه ال يجــوز محاكمتــه أو توقيــع أيــة عقوبــة عليــه‬\n      ‫‪ ،‬إذ كل مــا بــدر مــن موكلــي هــو التصــرف يف ملكــه ببيــع األرض‬\n      ‫كاملــة علــى شــخص قــام ببيعهــا علــى األفــراد الذيــن ال يوجــد بينهــم‬\n      ‫وبــن موكلــي أي تعامــل علــى اإلطــاق ‪ ،‬األمــر الــذي انتفــت معــه‬\n      ‫عالقــة الســببية بــن الفعــل الصــادر مــن موكلــي وهــو البيــع وبــن الفعــل‬\n                                             ‫املجــرم مــن وجهــة نظــر املدعــي العــام ‪.‬‬\n      ‫‪ -5‬أن الظاهــر يف إقامــة هــذه الدعــوى هــو احلســد والكيديــة ملوكلــي‬\n      ‫وألهــل الهجــرة التــي هــو فيهــا مــن قِ بــل بعــض أصحــاب الهجــر املجــاورة‬\n\n\n‫‪213‬‬\n\f‫وذلــك فقــد نســبوا ملوكلــي مــا هــو منــه بــراء ‪ ،‬وســبب ذلــك إقبــال الناس‬\n‫علــى شــراء األراضــي املجــاورة لهجرتهــم وعمرانهــا بعــد أن تعاونت معهم‬\n‫األمانــة بســفلتة الطــرق وشــركة الكهربــاء بإيصــال الكهربــاء إلى من‬\n‫يطلبــه والشــك أن االســتجابة ملثــل هــذه الشــكاوى التــي ال تبنــى علــى‬\n‫حــق خــاص وال حــق عــام إذ األرض ملوكلــي ال ينازعــه فيهــا أحــد تصرف‬\n‫فيهــا تصــرف املــاك وإشــغال احملكمــة بهــذه املطالبــة فيــه اســتجابة‬\n‫للدعــاوي الكيديــة وتكثيــر لهــا وهــو مــا يعــود بالضــرر العــام واخلــاص ‪.‬‬\n‫لــذا نطلــب مــن فضيلتكــم احلكــم بــرد الدعــوى واحلكــم ببــراءة‬\n‫موكلــي أ ‪ .‬ه ـ عليــه رفعــت اجللســة للتأمــل وأجلــت إلــى يــوم األثنــن‬\n‫‪1434/2/18‬ه ـ الســاعة التاســعة والنصــف صباح ـ ًا وأقفلــت اجللســة‬\n‫الســاعة العاشــرة والنصــف صباحــا وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/05‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافق‪1434/02/18‬ه ـ‬\n‫افتتحــت اجللســة الســاعة وفيهــا حضــر املدعــي العــام ووكيــل املدعــى‬\n‫عليــه وقــدم مذكــرة تتضمــن الئحــة الغرامــات واجلــزاءات عــن مخالفات‬\n‫البلديــة واملتضمنــة املــادة الرابعــة والتــي نصهــا (يجــوز التظلــم أمــام وزيــر‬\n‫الشــئون البلديــة والقرويــة مــن توقيــع أي عقوبــة مــن العقوبــات احملــددة‬\n‫يف هــذه الالئحــة خــال ســتني يومـ ًا مــن تاريــخ إبــاغ العقوبــة كمــا يجوز‬\n‫التظلــم مــن قــرار الوزيــر أمــام ديــوان املظالــم خــال ســتني يوم ًا مــن تاريخ‬\n‫إبــاغ القــرار ) وعليــه جــرى رفــع اجللســة للتأمــل يف يــوم األثنــن ‪/25‬‬\n‫‪1434/2‬ه ـ الســاعة العاشــرة والنصــف صباح ـ ًا وعليــه أقفلــت اجللســة‬\n‫الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/18‬ه ـ‬\n\n\n                                                                                         ‫‪214‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/02/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12.00‬وفيهــا حضــر املدعــي العــام ووكيــل‬\n      ‫املدعــى عليــه كمــا جــرى علــى االطــاع علــى الصــك الصــادر مــن‬\n      ‫احملكمــة العامــة مبكــة برقــم ‪ 16/31/111‬يف ‪1430/9/10‬ه ـ‬\n      ‫واملتضمــن النــزاع بــن املدعــى عليــه وطــرف آخــر علــى األرض محــل‬\n      ‫الدعــوى كمــا جــرى االطــاع علــى الالئحــة ووجــد بفقراتهــا املجوعــة‬\n      ‫الرابعــة مخالفــات البنــاء يف أرض حكوميــة غيــر مخططــة وأي مخالفــة‬\n      ‫ألنظمــة البنــاء ونــص يف الفقــرة ‪ 3 /4 /8‬مــن املــادة ‪ 4/14‬مينــع البنــاء يف‬\n      ‫األراضــي احلكوميــة غيــر املخططــة بــدون احلصــول علــى ترخيــص بنــاء‬\n      ‫نظامــي ســواء داخــل أو خــارج املخططــات الهيكليــة املعتمــدة للمــدن‬\n      ‫أو القــرى فبنــاء علــى مــا تقــدم ولكــون الدعــوى يف مخالفــات تختــص‬\n      ‫باجلانــب النظامــي وليــس اجلانــب الشــرعي وألن املخالفــة املوجــودة يف‬\n      ‫الدعــوى ضمــن املخالفــات مــن الالئحــة املشــار إليهــا ســابق ًا وملــا جــاء‬\n      ‫يف املــادة الثالثــة مــن نظــام االجــراءات اجلزائيــة والتنــي نصهــا ( ال يجــوز‬\n      ‫توقيــع عقوبــة جزائيــة علــى أي شــخص إال علــى أمــر محظــور ومعاقــب‬\n      ‫عليــه شــرع ًا أو نظامـ ًا ) وألن مــن اختصــاص احملكمــة النظــر ابتــداء يف‬\n      ‫االختصــاص وال يوجــد مســتند نظامــي يف نظــر احملكمــة لهــذا النــوع‬\n      ‫مــن القضايــا واألصــل أن لهــا واليــة محــددة لذلــك كلــه صرفــت النظــر‬\n      ‫عــن دعــوى املدعــي العــام وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n      ‫القناعــة باحلكــم كمــا قــرر املدعــي العــام اعتراضــه بالئحــة وجــرى‬\n      ‫تســليمه نســخة مــن القــرار الشــرعي وأفهــم بنظــام االســتئناف وأقفلــت‬\n      ‫اجللســة الســاعة الواحــدة ظهــر ًا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/19‬ه ـ‬\n\n\n‫‪215‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/06/19‬‬\n‫ه ـ افتتحــت اجللســة احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن‬\n‫املوافق‪1434/06/19‬ه ـ افتتحــت اجللســة وفيهــا عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف وبرفقهــا قرارهــا رقــم ‪ 34228267‬وتاريــخ‬\n‫‪1434/6/3‬ه ـ املتضمــن املوافقــة علــى احلكــم الصــادر منــا برقــم‬\n‫‪ 3448338‬وتاريــخ ‪1434/2/26‬ه ـ لــذا أمــرت باحلــاق ذلــك لضبطــه‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم‪ .‬حــرر يف ‪1434/06/19‬ه ـ وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/19‬هــ‪.‬‬\n\n\n\n\n                                                                            ‫‪216‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":207,"source_page_end":216,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bccafe17bd1a8de28a14c571f7f1cd49ec2410c10057dca890ba0db9c1245636","normalized_text_hash":"27baef91c0c49f2102beaf401f3e9a1fc4893d94db5a335051d9ca9f322cbaf5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p207-3448338"},{"id":"7a2d80a2-4fd8-534c-82ce-fac59f5ae428","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -عقار خارج اململكة -عدم اختصاص المحاكم بالدعاوى العينية املتعلقة بعقار خارج اململكة.","document_number":"34171136","case_number":"33530406","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/24","year":"1434","subject":"اختصاص -عقار خارج اململكة -عدم اختصاص المحاكم بالدعاوى العينية املتعلقة بعقار خارج اململكة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34171136 :‬تاريخه‪1434/3/24 :‬هـ‬\n                         ‫رقم الدعوى‪33530406 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3437336‬تاريخه‪1434/6/11 :‬هـ‬\n\n\n      ‫اختصــاص ‪ -‬عقــار خــارج اململكــة ‪ -‬عدم اختصاص احملاكم بالدعاوى‬\n                               ‫العينيــة املتعلقــة بعقار خارج اململكة‪.‬‬\n\n\n\n                                            ‫املادة ‪ 24‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه بــأن املدعــى عليــه ســجل‬\n      ‫نصيــب موكلــه بــأرض خــارج اململكــة يف فلســطني والعائــدة لهــم مــن‬\n      ‫إرث والدهــم باســمه منــذ أكثــر مــن ثالثــة عشــر عام ـ ًا ‪ ،‬وقــد أخــذ‬\n      ‫موكلــه حكمــا مــن محكمــة جــدة مــن حوالــي عشــر ســنوات مفــاده‬\n      ‫إرجــاع حصتــه مــن ارث والــده بــاألرض محــل الدعــوى واملذكــور ميلــك‬\n      ‫احلصــة األكبــر مــن األرض البالغــة مســاحتها ‪ 1061‬متــر مربــع وحصتــه‬\n      ‫تبلــغ ‪ 907‬متــر مربــع وموكلــه ميلــك ‪ 154‬متــر مربــع‪ ،‬ومــوكل املدعــي‬\n      ‫الوريــث الوحيــد الــذي لــم يســتلم ثمــن حصتــه حتــى اآلن‪ ،‬ويطلــب إمــا‬\n      ‫أن يشــتري املدعــى عليــه نصيــب موكلــه بســعر الســوق أو تبــاع كامــل‬\n      ‫األرض للغيــر ويأخــذ كل واحــد نصيبــه هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n      ‫عليــه بــأن الدعــوى مقامــة بخصــوص عقــار واقــع خــارج اململكــة ويطلــب‬\n      ‫صــرف النظــر عــن دعــوى املدعــي لعدم اختصاص محاكــم اململكة يف‬\n\n‫‪217‬‬\n\f‫نظــر هــذه الدعــوى ‪ -‬وبعــرض ذلــك علــى املدعــي وكالــة قــال ‪ :‬ســبق أن‬\n‫صــدر لــي حكــم مــن هــذه احملكمــة يف ذات الشــأن ‪ -‬فبنــاء علــى املــادة‬\n‫‪ 24‬مــن نظــام املرافعــات الشــرعية ونصهــا (تختــص محاكــم اململكــة‬\n‫بنظــر الدعــاوى التــي ترفــع علــى الســعودي ؛ ولــو لــم يكــن لــه محــل‬\n‫إقامــة عــام أو مختــار يف اململكــة ‪ ،‬فيمــا عــدا الدعــاوى العينيــة املتعلقــة‬\n‫بعقــار واقــع خــارج اململكــة) ‪ -‬ملــا تقــدم صــدر احلكــم بصــرف النظــر‬\n‫عــن دعــوى املدعــي لعــدم االختصــاص الدولــي حملاكــم اململكــة يف‬\n‫نظــر مثــل هــذه القضايــا ‪ -‬قــرر املدعــى عليــه القناعــة باحلكــم واعترض‬\n‫املدعــي وكالــة بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة الســابعة‬\n                           ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33530406‬‬\n‫وتاريــخ ‪1433/08/18‬ه ـ املقيــدة باحملكمــة برقــم ‪331551266‬‬\n‫وتاريــخ ‪1433/08/18‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/03/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر ‪ .....‬فلســطيني اجلنســية‬\n‫مبوجــب اإلقامــة رقــم ‪.....‬بصفتــه وكيــا عــن ‪ .....‬فلســطيني اجلنســية‬\n‫مبوجــب اإلقامــة رقــم ‪.....‬مبوجــب الوكالــة رقــم ‪ 33217527‬تاريــخ‬\n‫‪1433/8/10‬ه ـ الصــادرة مــن كتابــة عــدل الثانيــة باملدينــة املنــورة ‪،‬‬\n‫وادعــى علــى احلاضــر معــه ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقم ‪.....‬قائال ‪ :‬إن شــقيق موكلي ‪.....‬ســجل نصيب موكلي بأرض غزة‬\n\n                                                                                      ‫‪218‬‬\n\f      ‫والعائــدة لهــم مــن إرث والدهــم باســمه بتاريــخ ‪1999/8/30‬م أي أكثــر‬\n      ‫مــن ثالثــة عشــر ســنة ‪ ،‬وقــد أخــذ موكلــي حكمــا مــن محكمــة جــدة‬\n      ‫بتاريــخ ‪1423/11/26‬ه ـ أي مــن حوالــي عشــرة ســنوات مبوجــب صــك‬\n      ‫رقــم ‪ 15/555/7‬وتاريــخ ‪1424/1/7‬ه ـ مفــاده إرجــاع حصتــه مــن أرث‬\n      ‫والــده بــأرض غــزة ‪ ،‬واملذكــور ميلــك احلصــة األكبــر مــن األرض البالغة‬\n      ‫مســاحتها ‪ 1061‬متــر مربــع وحصتــه تبلــغ ‪ 907‬متــر مربــع وموكلــي‬\n      ‫ميلــك ‪ 154‬متــر مربــع ‪ ،‬وموكلــي الوريــث الوحيــد الــذي لــم يســتلم ثمــن‬\n      ‫حصتــه حتــى اآلن ‪ ،‬أرفــع لفضيلتكــم طلبــي هــذا بأنــه أمــا أن يشــتري‬\n      ‫نصيــب موكلــي بســعر الســوق أو أن نبيــع كامــل األرض للغيــر ويأخــذ‬\n      ‫كل واحــد نصيبــه هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n      ‫‪ :‬الدعــوى مقامــة بخصــوص عقــار واقــع خــارج اململكــة وأطلــب صــرف‬\n      ‫النظــر عــن دعــوى املدعــي لعــدم اختصــاص محاكــم اململكــة يف نظــر‬\n      ‫هــذه الدعــوى ‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال ‪ :‬ســبق أن صــدر‬\n      ‫لــي حكــم مــن هــذه احملكمــة يف ذات الشــأن ‪ .‬وبســؤاله عــن ذلــك‬\n      ‫احلكــم قــال ‪ :‬قضــى ذلــك الصــك بثبــوت مــا أقــر بــه املدعــى عليــه مــن‬\n      ‫أن ملوكلــي مســاحة قدرهــا مائــة وأربعــة وخمســون متــرا مربعــا مشــاع‬\n      ‫يف كامــل املســاحة البالغــة ألــف وواحــد وســتني متــرا مربعــا مــن األرض‬\n      ‫الواقعــة بحــي الرمــال يف مدينــة غــزة بفلســطني ‪ ،‬وبــه حكــم ‪.‬ثــم أبــرز‬\n      ‫املدعــي وكالــة صــورة مــن احلكــم املشــار إليــه مت إرفــاق نســخة منــه يف‬\n      ‫املعاملــة ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى املــادة‬\n      ‫‪ 24‬مــن نظــام املرافعــات الشــرعية والــذي ينــص علــى (تختــص محاكــم‬\n      ‫اململكــة بنظــر الدعــاوى التــي ترفــع علــى الســعودي ؛ ولــو لــم يكــن لــه‬\n      ‫محــل إقامــة عــام أو مختــار يف اململكــة ‪ ،‬فيمــا عــدا الدعــاوى العينيــة‬\n\n\n‫‪219‬‬\n\f‫املتعلقــة بعقــار واقــع خــارج اململكــة) ‪ ،‬فقــد حكمــت بصــرف النظــر‬\n‫عــن دعــوى املدعــي ‪ .....‬لعــدم االختصــاص الدولــي حملاكــم اململكــة يف‬\n‫نظــر مثــل هــذه القضايــا ‪ .‬وبعــرض احلكــم قــرر املدعــى عليــه القناعــة‬\n‫وقــرر املدعــي وكالــة االعتــراض ‪ ،‬وجــرى تســليمه نســخة مــن احلكــم‬\n‫وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال‬\n‫ســقط حقــه يف االعتــراض‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت‬\n‫اجللســة الســاعة ‪ . 11 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/24‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ‬\n‫فقــد جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة املســاعد مبحافظــة جــدة برقــم‬\n‫‪ 331551266‬وتاريــخ ‪1434/05/26‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ ‪.....‬القاضــي باحملكمــة العامــة مبحافظــة جــدة املســجل‬\n‫برقــم ‪ 34171136‬وتاريــخ ‪1434/03/24‬ه ـ املتضمــن دعــوى ‪.....‬‬\n‫فلســطيني اجلنســية ضد ‪ ،.....‬وبدراســة الصك وص ــورة ضبط ــه والئحته‬\n‫االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم بصــرف النظــر عــن الدعــوى‬\n‫لعــدم االختصــاص الدولــي حملاكــم اململكــة يف نظــر هــذه الدعــوى‬\n‫واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪220‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":217,"source_page_end":220,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6e792fc83d41e8ecc7d7a6e5f4ea0f1d12f1793e2deacaf3c7f03292aa6ab276","normalized_text_hash":"d6553d73c4d19eba5848ec0ad3cedc83cc2f149a13a667da11253e287057b800","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p217-34171136"},{"id":"99747ca6-7c7c-5bc5-a21d-353100c65755","document_type":"judgment","category":"judicial","subcategory":"general","title":"-عدم التجاوب مع رجل األمن اثناء تأدية عمله -نظام مكافحة الرشوة والتزوير -صرف نظر لعدم االختصاص.","document_number":"34352250","case_number":"34177806","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/6","year":"1434","subject":"-عدم التجاوب مع رجل األمن اثناء تأدية عمله -نظام مكافحة الرشوة والتزوير -صرف نظر لعدم االختصاص.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34352250 :‬تاريخه‪1434/11/6 :‬هـ‬\n                         ‫رقم الدعوى‪34177806 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34380392‬تاريخه‪1434/12/17 :‬هـ‬\n\n\n      ‫عــدم اختصــاص احملكمــة بنظــر قضايــا االعتــداء علــى رجــل األمــن‬\n      ‫‪ -‬عــدم التجــاوب مــع رجــل األمــن اثنــاء تأديــة عملــه ‪ -‬نظــام مكافحــة‬\n                        ‫الرشــوة والتزويــر ‪ -‬صــرف نظــر لعــدم االختصــاص‪.‬‬\n\n\n\n\n                         ‫‪ -‬املادة السابعة من نظام مكافحة الرشوة والتزوير ‪.‬‬\n                      ‫‪ -‬تعميم وزارة الداخلية رقم ‪ 118012‬يف ‪1430/10/26‬هـ‬\n                                   ‫‪ -‬املادة (‪ )72‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫اتهــام املدعــي العــام للمدعــى عليــه بعــدم التجاوب مع رجــال األمن يطلب‬\n      ‫إدانتــه وتعزيــره شــرعا ‪ -‬احلكــم بصــرف النظــر لعــدم االختصــاص ‪-‬‬\n      ‫قــرر املدعــي العــام االعتــراض وطلــب االســتئناف بــدون الئحــة ‪ -‬صــدق‬\n                                            ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪............‬القاضــي يف احملكمــة العامــة‬\n      ‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعرعــر برقــم ‪ 34177806‬وتاريــخ ‪ 1434/04/17‬ه ـ املقيــدة‬\n\n‫‪221‬‬\n\f‫باحملكمــة برقــم ‪ 34949222‬وتاريــخ ‪ 1434/04/17‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1434/11/05‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 00‬‬\n‫ا بصفتــي مدعي ـ ًا عام ـ ًا‬‫وفيهــا حضــر املدعــي العــام ‪ ..........‬وقــرر قائ ـ ً‬\n‫بدائــرة االدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود الشــمالية أدعــي علــى‬\n‫‪.......‬ســعودي اجلنســية مبوجب الســجل املدني رقم‪ )..........(/‬فإنه يف يوم‬\n‫االثنــن املوافــق ‪1434/3/9‬ه ـ تلقــى مركــز شــرطة اخلالديــة احملضــر‬\n‫املعــد مــن قبــل الدوريــات األمنيــة الراجلــه يف ســوق املجوهــرات املتضمــن‬\n‫قيــام املواطــن ‪(........... /‬مت حفــظ االتهــام بحقــه اســتناد ًا للمــادة (‪)62‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة ) وشــقيقه املتهــم‪ ....../‬بالتجمهــر أمــام‬\n‫أحــد الباعــة املتجولــن فتــم توجيــه البائــع بعــدم إحــداث جتمهــر يف ســوق‬\n‫املجوهــرات فقــام املواطــن ‪..... /‬باإلشــارة بيــده بطريقــة اســتهزائية وقــال‬\n‫( تعــال تعــال وش عنــدك ) وعنــد طلــب هوياتهــم رفــض املتهــم ‪..... /‬إبرازه‬\n‫(مت فــرز أوراق مســتقلة وأحيلــت جلهــة االختصــاص ملخالفتــه املــادة(‪)69‬‬\n‫مــن نظــام األحــوال املدنيــة الصــادر باملرســوم امللكــي رقــم (م‪ )7/‬وتاريخ‬\n‫‪1407/4/20‬هــ) وقــال لرجــل األمــن (كالمـ ًا غيــر الئــق) وعنــد حضــور‬\n‫الدوريــة األمنيــة رفــض املتهــم ‪...... /‬الركــوب وقــام بدفــع رجــل األمــن ‪/‬‬\n‫‪...........‬وقــال (تبطــي تركبنــي الدوريــة) ‪ .‬وبضبــط إفــادة رجــل اجلنــدي‬\n‫‪........ /‬أفــاد بأنــه شــاهد رجــل األمــن ‪.......... /‬متوقــف امــام املواطــن‬\n‫‪ ......../‬وشــقيقه املتهــم ‪ ...../‬وســمع املتهــم ‪....... /‬وهــو يقــول ( بــأي تهمــة‬\n‫تركبنــي الدوريــة ) وأنــه عنــد محاولــة إركابــه للدوريــة قــام بدفــع يــد‬\n‫رجــل األمــن ‪..... /‬عنــه ‪ .‬وبضبــط افــادة رجــل األمــن اجلنــدي أول ‪...... /‬‬\n‫أفــاد بأنــه شــاهد جتمهــر عنــد أحــد الباعــة فطلــب منــه عــدم التجمهــر‬\n‫فقــال لــه املواطــن ‪......... /‬تعــال تعــال وهــو يســتهزئ فطلــب منــه ومــن‬\n\n\n                                                                                          ‫‪222‬‬\n\f      ‫شــقيقه املتهــم ‪ ...../‬اإلثبــات فرفــض املتهــم‪ ........./‬إبــرازه وقــال لــه (وش‬\n      ‫حضرتــك ) وعنــد محاولــة إركابــه للدوريــة قــام بإبعــاد يــده عنــه وقــال‬\n      ‫(وخــر أنــا أروح بســيارتي )‪ .‬وباســتجوابه ‪ /‬نفــى قيامــه بدفــع رجــل األمــن‬\n      ‫‪........ /‬بيــده أو أنــه قــال لــه ‪ (:‬تبطــي تركبنــي الدوريــة ) وانــه عندمــا‬\n      ‫طلــب منــه الركــوب يف الدوريــة ركــب ‪ .‬وقــد انتهــى التحقيــق إلــى اتهــام‬\n      ‫‪ ......../‬بعــدم التجــاوب مــع رجــال األمــن‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ -1‬مــا جــاء يف احملضــر املعــد مــن قبــل الدوريــات األمنيــة املــدون علــى‬\n                                                                         ‫اللفــة رقــم (‪.)5‬‬\n      ‫‪ -2‬مــا جــاء يف محضــر ضبــط إفــادة اجلنــدي ‪ .........../‬علــى اللفــة رقــم‬\n                                                                                       ‫(‪.)16‬‬\n      ‫‪ -3‬مــا جــاء يف محضــر ضبــط إفــادة اجلنــدي ‪......... /‬علــى اللفــة رقــم‬\n      ‫(‪ .)19‬وحيــث إن مــا أقــدم عليــه املتهــم املذكــور وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ممــا يتعــن معــه إحالتــه‬\n      ‫للمحكمــة املختصــة لطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                 ‫بعقوبــة تعزيريــة تزجــره وتــردع غيــره‪.‬‬\n      ‫(علمـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل) فبنــاء علــى مــا تقــدم مــن دعــوى‬\n      ‫املدعــي العــام وملــا جــاء يف املــادة الســابعة مــن نظــام مكافحــة الرشــوة‬\n      ‫والتزويــر الصــادر بالقــرار رقــم (‪ )175‬يف ‪1428/12/28‬ه ـ والتــي‬\n      ‫تنــص علــى أنــه «يعاقــب بالعقوبــة املنصــوص عليهــا يف املــادة األولــى مــن‬\n      ‫النظــام نفســه مــن يســتعمل القــوة أو العنــف أو التهديــد يف حــق موظــف‬\n      ‫عــام حلصــل منــه علــى قضــاء أمــر غيــر مشــروع أو ليحميــه علــى اجتنــاب‬\n      ‫أداء عمــل مــن األعمــال املكلــف بهــا نظام ـاً» واملؤكــد عليــه بتعميــم‬\n      ‫صاحــب الســمو امللكــي وزيــر الداخليــة ‪-‬رحمــه اهلل ‪ -‬رقــم ‪118012‬‬\n\n\n‫‪223‬‬\n\f‫يف ‪1430/10/26‬ه ـ وقــد جــاء يف الفقــرة الثانيــة منــه مــا يلــي (‪2‬ـ‬\n‫األفعــال التــي يرتكبهــا املتهــم خــارج حــاالت القبــض وتكــون املبــادرة‬\n‫باالعتــداء أو التهديــد منــه كأن يقــوم رجــل الســلطة العامــة مبمارســة‬\n‫عملــه فيبــادر املتهــم باالعتــداء أو بتهديــده ملنعــه مــن أداء العمــل أو حملــه‬\n‫علــى أداء عمــل يخالــف النظــام يكــون االختصــاص فيهــا لهيئــة الرقابــة‬\n                                                               ‫والتحقيــق ‪ .)..‬ا‪.‬هــ‪.‬‬\n‫وحيــث أن مــا صــدر مــن املدعــى عليــه مــن أفعــال يصــدق عليهــا‬\n‫األوصــاف الــواردة يف نظــام الرشــوة بعاليــة والتعميــم املشــار إليــه‪،‬‬\n‫حيــث أنــه فعــل خــارج حــاالت القبــض ولــم توجــد جرميــة ســابقة تســتلزم‬\n‫القبــض وكانــت املبــادرة باالعتــداء منــه وبنــاء علــى املــادة (‪ )72‬مــن‬\n‫نظــام املرافعــات الشــرعية والتــي تنــص علــى أن «الدفــع بعــدم اختصــاص‬\n‫احملكمــة النوعــي أو الدفــع بعــدم قبــول الدعــوى النعــدام الصفــة أو‬\n‫األهليــة أو املصلحــة أو ألي ســبب آخــر وكذلــك الدفــع فعــدم ســماع‬\n‫الدعــوى حتكــم بــه احملكمــة مــن تلقــاء نفســها ويجــوز الدفــع بــه يف‬\n‫أي مرحلــة تكــون الدعــوى فيهــا» ا‪.‬هــ‪ .‬لذلــك كلــه فقــد حكمــت‬\n‫بعــدم اختصاصــي بنظــر هــذه الدعــوى نوعيـ ًا وأن املختــص بنظرهــا هــي‬\n‫احملكمــة اإلداريــة بديــوان املظالــم بنــاء علــى املــادة الســابعة مــن نظــام‬\n‫مكافحــة الرشــوة املشــار إليهــا بعاليــه‪ .‬وبعــرض احلكــم علــى املدعــي‬\n‫العــام قــرر اعتراضــه بــدون الئحــة اعتراضيــة‪ .‬وبــاهلل التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف يــوم األربعــاء‬\n                                                      ‫املوافــق ‪1434/11/05‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n\n\n                                                                                        ‫‪224‬‬\n\f      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم‬\n      ‫‪ 34949222‬وتاريــخ ‪1434/11/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪............ /‬املســجل برقم ‪34352250‬‬\n      ‫وتاريــخ ‪1434/11/6‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪......... /‬‬\n      ‫التهامــه بعــدم التجــاوب مــع رجــال االمــن وقــد تضمــن القــرار حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة فقــد قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى‬\n                              ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪225‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":221,"source_page_end":225,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"84149328b80447e733d973d565dec7a77f9786ab49cb1c74b2150dcc7ccb22a8","normalized_text_hash":"ba58b7bc430b7fee5a7c50f1358460653201bdb3ec2831c90bbfad8f6234f52f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p221-34352250"},{"id":"bda9749f-502e-5bf9-8bf8-f358ac8bc9af","document_type":"judgment","category":"judicial","subcategory":"general","title":"-1املادة ( )141من نظام االجراءات اجلزائية. -2قواعد االختصاص بنظام املطبوعات والنشر.","document_number":"34263116","case_number":"34180880","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"-1املادة ( )141من نظام االجراءات اجلزائية. -2قواعد االختصاص بنظام املطبوعات والنشر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34263116 :‬تاريخه‪1434/7/9:‬هـ‬\n                  ‫رقم الدعوى‪34180880 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34311259‬تاريخه‪1434/9/2 :‬هـ‬\n\n\n‫نشــر أخبــار وأســرار وصــور ســريه ‪ ،‬نشــر صحفــي لوثيقــة حكوميــة‬\n‫ســرية ‪ ،‬التســتر علــى مســرب الوثيقــة ‪ ،‬عــدم اختصــاص نوعــي ‪ ،‬صــرف‬\n                ‫النظــر عــن دعــوى املدعــي العــام لعــدم االختصــاص ‪.‬‬\n\n\n\n\n                          ‫‪ -1‬املادة (‪ )141‬من نظام االجراءات اجلزائية‪.‬‬\n                       ‫‪ -2‬قواعد االختصاص بنظام املطبوعات والنشر‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بنشــر وثيقــة‬\n‫حكوميــة ســرية والتســتر علــى مــن ســلمها لــه وطلــب إيقــاع العقوبــة‬\n‫التعزيريــة عليــه ‪ ،‬حضــر املدعــى عليــه وأقــر بأنــه تلقــى اتصــا ًال مــن‬\n‫مجهــول وأفــاده مبعلومــة فطلــب منــه إثباتهــا فأرســل لــه الوثيقــة عبــر‬\n‫الناســوخ وأبلــغ إدارة التحريــر بهــا وطلبــوا منــه التواصــل مــع احملكمــة‬\n‫إال أنــه لــم يتمكــن لكونــه موظفــا يف شــركة خاصــة وقــام باالتصــال‬\n‫علــى احملكمــة فلــم يجبــه أحــد وأخبــر إدارة التحريــر بذلــك ثــم فوجــئ‬\n‫بنشــر الوثيقــة يف الصحيفــة ‪ ،‬وملــا ظهــر بــأن املدعــى عليــه صحفــي‬\n‫فقــد صرفــت احملكمــة النظــر عــن القضيــة لكونهــا خاضعــة لنظــام‬\n‫املطبوعــات والنشــر ‪ ،‬اعتــرض املدعــي العــام وقــدم الئحتــه االعتراضيــة‬\n\n                                                                                  ‫‪226‬‬\n\f                                     ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن ‪1434/4/22‬ه ـ لــدي‬\n      ‫ـاء علــى املعاملــة‬\n                         ‫‪..........‬مســاعد رئيــس احملكمــة اجلزائيــة بأبهــا بنـ ً‬\n      ‫الــواردة إلينــا مــن هيئــة التحقيــق واالدعــاء العــام مبنطقــة عســير برقــم‬\n      ‫‪ 34180880‬يف ‪1434/ 4/ 20‬ه ـ واملقيــدة بقيــد احملكمــة بالقيــد رقــم‬\n      ‫‪ 34965514‬يف ‪1434/4/ 20‬ه ـ ففــي الســاعة الواحــدة والربــع ظ ًهــرا‬\n      ‫فتحــت اجللســة األولــى وفيهــا حضــر املدعــي العــام املكلــف ‪..........‬‬\n      ‫مبوجــب خطــاب التكليــف رقــم ‪..........‬يف ‪1430/9/9‬ه ـ وقــدم الدعــوى‬\n      ‫احملــررة واملتضمنــة توجيــه االتهــام للمدعــى عليــه‪.......... /‬ســعودي‬\n      ‫بالهويــة الوطنيــة رقــم (‪ )..........‬يبلــغ مــن العمــر وقــت اجلرميــة ( ‪)31‬‬\n      ‫عامــا مطلــق الســراح بنشــر وثيقــة ســرية والتســتر علــى مــن ســلمه إياهــا‬\n      ‫واملعاقــب علــى ذلــك وفــق تعميــم صاحــب الســمو امللكــي نائــب رئيــس‬\n      ‫مجلــس الــوزراء( ‪/720‬م ) وتاريــخ ‪1416/4/3‬ه ـ وذلــك لألدلــة والقرائن‬\n      ‫التاليــة ‪ -1 :‬مــا جــاء يف إقــراره املشــار إليــه واملــدون علــى الصفحــات رقــم‬\n      ‫(‪5‬ـ ـ ‪ 6‬ـ ـ ‪ )7‬مــن دفتــر التحقيــق املرفــق ‪ 2‬ـ ـ صــور الوثيقــة املرفقة باألوراق‬\n      ‫لفــه رقــم (‪ ) 4-3‬وبالبحــث عــن ســوابقه لــم يعثــر علــى ســوابق مســجلة‬\n      ‫وحيــث أن مــا أقــدم عليــه املدعــى عليــه املذكــور فعــل محــرم مخالــف‬\n      ‫للتعليمــات وإفشــاء لســرية املكاتبــات الســرية ‪ ،‬أطلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره هــذا مــا جــاء يف‬\n      ‫الدعــوى العامــة وألن املدعــى عليــه لم يحضر رغــم تبلغه باملوعد مبوجب‬\n      ‫إفــادة مشــرف املكتــب املدونــة علــى أوراق املعاملــة وبنــاء علــى مــا جــاء‬\n\n‫‪227‬‬\n\f‫يف املــادة (‪ )141‬مــن نظــام االجــراءات اجلزائيــة التــي نصــت علــى أنــه إذا‬\n‫لــم يحضــر املتهــم املكلــف باحلضــور حســب النظــام يف اليــوم املعــن ولــم‬\n‫يرســل وكيــا عنــه فيســمع القاضــي دعــوى املدعــي وبيناتــه ويرصدهــا‬\n‫يف ضبــط القضيــة وال يحكــم إال بعــد حضــور املتهــم ‪ :‬وبنــاء عليــه جــرى‬\n‫ســؤال املدعــي العــام عمــا لديــه مــن بينــه تثبــت مــا نســبه للمدعــى عليــه‬\n‫فأجــاب بــأن بينتــي هــي مــا جــاء يف إقــرار املدعــى عليــه واملــدون علــى‬\n‫الصفحــات مــن ( ‪ 5‬ـ ـ ‪ )7‬مــن دفتــر التحقيــق املرفــق لفــة ( ‪ ) 9‬باملعاملــة‬\n‫وكذلــك صــورة الوثيقــة املرفقــة بــاألوراق لفــة ( ‪ 3‬ـ ـ ‪ ) 4‬هــذا مــا لــدي‬\n‫مــن أدلــة وقرائــن أشــرت اليهــا ســابق ًا يف الئحــة الدعــوى العامــة وليــس‬\n‫لــدي بينــه غيرهــا هكــذا قــرر وباالطــاع علــى مــا جــاء يف إقــرار املدعى‬\n‫عليــه حتقيقــا املــدون علــى الصفحــات املشــار إليهــا وجدتــه يتضمــن‬\n‫إقــرار املدعــى عليــه بنشــر اخلبــر وأنــه حصــل علــى اخلطــاب الســري عــن‬\n‫طريــق الفاكــس مــن أحــد األشــخاص وأنــه ال يعــرف هــذا الشــخص‬\n‫وأنــه لــم يطلبــه شــخصيا وإمنــا اتصــل مبكتــب صحيفــة ‪....................‬‬\n‫وأخبــره مبضمــون اخلطــاب وانــه ال يذكــر رقــم املتصــل وأنــه ال يعلــم‬\n‫بــأن اخلطــاب مكتــوب عليــه ســري إال يــوم التحقيــق وأنــه ال ميلــك أي‬\n‫معــرف ملنتــدى ‪..........‬وال يعــرف الشــخص املدعــو ‪..........‬صاحــب املعــرف‬\n‫يف منتــدى ‪ ..........‬هــذا مــا تضمنــه إقــرار املدعــى عليــه املــدون يف دفتــر‬\n‫التحقيــق وباالطــاع علــى صــورة الوثيقــة املرفقــة وجدتهــا كمــا ذكــر‬\n‫املدعــي العــام يف الئحــة الدعــوى العامــة وقــد نشــرت كمــا هــي يف‬\n‫منتديــات ‪..........‬وحتــى إحضــار املدعــى عليــه وعــرض الدعــوى العامــة‬\n‫عليــه والبينــات التــي أســتند عليهــا املدعــي العــام جــرى رفــع هــذه اجللســة‬\n‫ويف يوم الســبت ‪1434/6/3‬هـ افتتحت اجللســة الثانية الســاعة العاشــرة‬\n\n\n                                                                                       ‫‪228‬‬\n\f      ‫صباح ـ ًا وفيهــا حضــر املدعــي العــام وحضــر املدعــى عليــه وبعــرض مــا‬\n      ‫ا بأننــي تلقيــت‬  ‫جــاء يف الدعــوى العامــة علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫اتصــا ًال مــن شــخص ال أعرفــه وأفادنــي مبعلومــة وطلبــت منــه مــا يثبــت‬\n      ‫ذلــك فأرســل لــي عــن طريــق الفاكــس الوثيقــة وأبلغــت إدارة التحريــر‬\n      ‫بذلــك وطلبــوا منــي التواصــل مــع احملكمــة وألنــي موظــف يف شــركة‬\n      ‫‪ ..........‬وعملــي مــن الســاعة الســابعة وحتــى الثالثــة مســاء لــم أســتطع‬\n      ‫الذهــاب للمحكمــة وقمــت باالتصــال علــى ســنترال احملكمــة ولــم‬\n      ‫يجــب أحــد وأخبــرت إدارة التحريــر بذلــك ثــم إنــي فوجئــت بنشــر الوثيقــة‬\n      ‫يف الصحيفــة هــذا مــا حصــل هكــذا أجــاب وألجــل التأمــل يف الدعــوى‬\n      ‫جــرى رفــع اجللســة حتــى يــوم األحــد ‪1434/7/9‬ه ـ الســاعة التاســعة‬\n      ‫والنصــف ويف يــوم األحــد ‪1434/7/9‬ه ـ فتحــت اجللســة الثالثــة الســاعة‬\n      ‫التاســعة والنصــف وفيهــا حضــر املدعــي العــام واملدعــى عليــه فبنــاء علــى‬\n      ‫مــا ســبق مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه يعمــل صحفــي يف‬\n      ‫صحيفــة رســمية تخضــع ألنظمــة وزارة الثقافــة واإلعــام وألن النظــر يف‬\n      ‫مخالفــات النشــر اختصــت بــه جلــان خصصــت للنظــر مبخالفــات النشــر‬\n      ‫ولــذا صرفــت النظــر عــن دعــوى املدعــي العــام ضــد املدعــى عليــه لعــدم‬\n      ‫االختصــاص النوعــي وبهــذا حكمــت وبعــرض احلكــم قــرر املدعــي‬\n      ‫العــام االعتــراض وطالــب باالســتئناف وتقــدمي الئحــة اعتراضيــة علــى‬\n      ‫احلكــم فأجيــب لطلبــه وقــد ســلم نســخة مــن احلكــم يف هــذه اجللســة‬\n      ‫وقــرر املدعــى عليــه القناعــة باحلكــم وعليــه جــرى التوقيــع وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد حــرر الســاعة احلاديــة عشــر ‪ .‬احلمــد هلل وحده ثم‬\n      ‫إنــه يف هــذا اليــوم االثنــن ‪1434/8/8‬ه ـ فتحــت اجللســة الرابعــة الســاعة‬\n      ‫الثانيــة عشــرة وخمســة عشــرة دقيقــة وفيهــا حضــر املدعــي العــام وســلم‬\n\n\n‫‪229‬‬\n\f‫الالئحــة االعتراضيــة املكونــة مــن خمــس صفحــات وباالطــاع عليهــا‬\n‫لــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه وصلــى اهلل وســلم علــى نبينــا‬\n                      ‫محمــد حــرر الســاعة الثانيــة عشــرة وعشــرين دقيقــة‬\n‫احلمــد هلل وحــده ثــم إنــه عادت املعاملة من محكمة االســتئناف مبنطقة‬\n‫عســير مرفقــا بهــا قــرار الدائــرة اجلزائيــة الرابعــة برقــم ‪34311259‬‬\n‫وتاريــخ ‪1434/9/2‬ه ـ واملتضمــن املوافقــة علــى احلكــم واهلل املوفــق‬\n                                       ‫وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                                        ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":226,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"acb13795dfc290a865b946d91d7906b6ecb98485f90eaa03f33dfe671e7a4ae0","normalized_text_hash":"15243f71ca6d809de1bb9bf3a9f18e61ccaaec1da5cfef01b31d7485ecdc3d22","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p226-34263116"},{"id":"87102380-4327-5bac-916d-565fdd61c169","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -قسمة تركة -دفع املدعى عليه بعدم اختصاص المحكمة إلقامة غالبية الورثة (املدعى عليهم) يف بلد آخر -إفهام املدعية مبعنى االختصاص املكاني قبل احلكم يف الدعوى -إقرار املدعية مبحل إقامة املدعى عليهم -انعقاد االختصاص للمحكمة محل إقامة األكثرية حال تعدد املدعى عليهم -صرف النظر عن الدعوى لعدم االختصاص .","document_number":"34204578","case_number":"33681138","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"اختصاص -قسمة تركة -دفع املدعى عليه بعدم اختصاص المحكمة إلقامة غالبية الورثة (املدعى عليهم) يف بلد آخر -إفهام املدعية مبعنى االختصاص املكاني قبل احلكم يف الدعوى -إقرار املدعية مبحل إقامة املدعى عليهم -انعقاد االختصاص للمحكمة محل إقامة األكثرية حال تعدد املدعى عليهم -صرف النظر عن الدعوى لعدم االختصاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34204578 :‬تاريخه‪1434/5/4 :‬هـ‬\n                         ‫رقم الدعوى‪33681138 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34242695‬تاريخه‪1434/6/17 :‬هـ‬\n\n\n      ‫اختصــاص ‪ -‬قســمة تركــة ‪ -‬دفــع املدعــى عليــه بعــدم اختصــاص‬\n      ‫احملكمــة إلقامــة غالبيــة الورثــة (املدعــى عليهــم) يف بلــد آخــر‪ -‬إفهــام‬\n      ‫املدعيــة مبعنــى االختصــاص املكانــي قبــل احلكــم يف الدعــوى‪ -‬إقــرار‬\n      ‫املدعيــة مبحــل إقامــة املدعــى عليهــم‪ -‬انعقــاد االختصــاص للمحكمــة‬\n      ‫محــل إقامــة األكثريــة حــال تعــدد املدعــى عليهــم‪ -‬صــرف النظــر عــن‬\n                                                    ‫الدعــوى لعــدم االختصــاص ‪.‬‬\n\n\n\n                          ‫املادة الرابعة والثالثون من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه بــأن مورثهــم قــد تــويف وخلــف تركــة‬\n      ‫مــن ضمنهــا عقــارات يف املدينــة النبويــة وأمــوال نقديــة وتطلــب قســمتها‬\n      ‫بــن الورثــة هكــذا ادعــت ‪ -‬بســؤالها عــن وصــف العقــارات أجابت بعدم‬\n      ‫معرفتهــا أرقامهــا وليــس عندهــا صــورة مــن صكوكهــا ‪ -‬قــرر املدعــى‬\n      ‫عليــه أن الورثــة يقيمــون يف مدينــة الريــاض ويطلــب صــرف النظــر عــن‬\n      ‫دعــوى املدعيــة لعــدم االختصــاص هكــذا قــرر ‪ -‬بعــرض ذلــك علــى‬\n      ‫املدعيــة أجابــت قائلــة بــأن ســبعة مــن الورثــة يقيمــون يف الرياض وخمســة‬\n      ‫منهم يف جدة وواحد منهم يف املدينة وتختار إقامة الدعوى يف محكمة‬\n\n‫‪231‬‬\n\f‫جــدة ‪ -‬عنــد ذلــك جــرى إفهامهــا بــأن االختصــاص املكانــي للمحكمــة‬\n‫العامــة بالريــاض فطلبــت البــت يف الدعــوى ‪ -‬ألن املدعــى عليهــا قــررت‬\n‫ان أكثــر الورثــة يقيمــون يف مدينــة الريــاض ‪ -‬وبنــاء علــى املــادة الرابعــة‬\n‫والثالثــن مــن نظــام املرافعــات الشــرعية ونــص احلاجــة منهــا‪ . .( :‬واذا‬\n‫تعــدد املدعــى عليهــم كان االختصــاص للمحكمــة التــي يقــع يف نطاقــه‬\n‫اختصاصهــا محــل إقامــة األكثريــة) ‪ -‬ملــا تقــدم صــدر احلكــم بصــرف‬\n‫النظــر عــن دعــوى املدعيــة لعــدم االختصــاص املكانــي‪ -‬قــرر املدعــى‬\n‫عليــه قناعتــه باحلكــم واعترضــت املدعيــة بالئحــة ‪ -‬صــدق احلكــم‬\n‫مــن الدائــرة احلقوقيــة اخلامســة مبحكمــة االســتئناف مبنطقــة مكــة‬\n                                                                       ‫املكرمــة ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33681138‬وتاريــخ‬\n‫‪ 1433/11/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332139020‬وتاريــخ‬\n‫‪ 1433/11/28‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/05/04‬ه ـ حضرت‬\n‫‪.........‬ســعودية اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪.........‬باألصالــة عــن‬\n‫نفســها وبصفتهــا وليــة علــى ابنائهــا القاصريــن ‪......... ......... ......... .........‬‬\n‫أوالد ‪.........‬مبوجــب صــك الواليــة الصــادر مــن احملكمــة العامــة بجــدة‬\n‫رقــم ‪ ...........‬يف ‪1432/11/3‬ه ـ واملعــرف بهــا مــن قبــل ‪.........‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪.........‬وحضــر حلضورهمــا ‪.........‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .........‬أصالــة عــن‬\n\n                                                                                              ‫‪232‬‬\n\f      ‫نفســه وبصفتــه وكيــا عــن ‪ .........‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة العــدل مبحافظــة الدرعيــة رقــم ‪ 32248266‬يف ‪1432/9/22‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق والبيــع والشــراء واالفــراغ واملداعــاة واملخاصمــة‬\n      ‫وأيــة مســتحقات ماليــة عائــدة لــي بــاإلرث مــن مــورث موكلــه والوكيــل‬\n      ‫عــن ‪ .........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل مبحافظــة‬\n      ‫الدرعيــة رقــم ‪ 32248332‬يف ‪1432/9/22‬ه ـ واملخــول لــه فيهــا حــق‬\n      ‫اســتالم مــا يخــص موكلــه مــن تركــة مورثــه والبيــع للثابــت واملنقــول‬\n      ‫واالفــراغ والصلــح والوكيــل عــن ‪ ......... ......... ......... .........‬بنــات ‪.........‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل بالعرقة رقــم ‪32344173‬‬\n      ‫يف ‪1432/12/2‬ه ـ واملخــول لــه فيهــا حــق البيــع والشــراء واالفــراغ‬\n      ‫وقبولــه واســتالم الثمــن وتســليم املثمــن وايــة مســتحقات ماليــة عائــدة لــي‬\n      ‫بــاإلرث مــن مــورث موكليــه والوكيــل عــن بليــه ‪.........‬مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة رقــم ‪73574‬‬\n      ‫يف ‪1432/12/23‬ه ـ واملخــول لــه فيهــا حــق البيــع والشــراء واالفــراغ‬\n      ‫واملداعــاة واملخاصمــة واســتالم جميــع مــا يخــص موكلتــه مــن ارث‬\n      ‫مورثــه وبســؤاله عــن صــك حصــر الورثــة ابــرزه وباالطــاع عليــه وجدنــاه‬\n      ‫صــادرا مــن احملكمــة العامــة بالريــاض ويحمــل الرقــم ‪32260483‬‬\n      ‫يف ‪1432/10/13‬ه ـ واملتضمــن وفــاة ‪.........‬بتاريــخ ‪1432/9/16‬ه ـ‬\n      ‫وانحصــار ارثــه يف امــه ‪ .........‬ويف زوجتــه ‪ .........‬و‪ .........‬ويف ابنائــه ‪.........‬‬\n      ‫‪......... ......... ......... .........‬املولــود يف ‪1426/11/13‬ه ـ ويف بناتــه ‪.........‬‬\n      ‫‪ ......... .........‬والقاصرات ‪.........‬املولودة يف ‪1422/9/23‬هـ ‪.........‬املولودة‬\n      ‫يف ‪1425/5/6‬هـ ‪ .........‬املولودة يف ‪1428/10/15‬هـ ال وارث له سواهم‬\n      ‫ا‪.‬ه ـ فادعــت األولــى قائلــة ان مورثنــا ‪.........‬قــد تــويف وخلــف تركــة مــن‬\n\n\n‫‪233‬‬\n\f‫ضمنهــا عقــارات يف املدينــة النبويــة وامــوال نقديــة أطلــب قســمتها بــن‬\n‫الورثــة هكــذا ادعــت وبســؤالها عــن وصــف العقــارات أجابــت قائلــة ال‬\n‫اعــرف ارقامهــا وليــس عنــدي صــورة مــن صكوكهــا هكــذا أجابــت‬\n‫ثــم قــرر املدعــى عليــه وكالــة قائــا ان الورثــة يقيمون يف مدينــة الرياض‬\n‫واطلــب صــرف النظــر عــن دعــوى املدعيــة لعــدم االختصــاص هكــذا‬\n‫قــرر وبعــرض ذلــك علــى املدعيــة اجابــت قائلــة ســبعة مــن الورثــة يقيمــون‬\n‫يف الريــاض وخمســة منهــم يف جــدة وواحــد منهــم يف املدينــة وانــا اختــار‬\n‫اقامــة الدعــوى يف محكمــة جــدة هكــذا أجابــت عنــد ذلــك أفهمتهــا‬\n‫بــأن االختصــاص املكانــي للمحكمــة العامــة بالريــاض فقــررت قائلــة‬\n‫أطلــب البــت يف دعــواي انــا غيــر مســتعده للذهــاب للريــاض هكــذا‬\n‫قــررت فبنــاء علــى مــا ســلف وألن املدعــى عليهــا قــررت ان أكثــر الورثــة‬\n‫يقيمــون يف مدينــة الريــاض وبنــاء علــى املــادة الرابعــة والثالثــون مــن نظام‬\n‫املرافعــات الشــرعية ونــص احلاجــة منهــا‪ . . .( :‬واذا تعــدد املدعــى عليهــم‬\n‫كان االختصــاص للمحكمــة التــي يقــع يف نطاقــه اختصاصهــا محــل‬\n‫اقامــة االكثريــة) لذلــك فقــد صرفــت النظــر عــن دعــوى املدعيــة لعــدم‬\n‫االختصــاص املكانــي وبذلــك حكمــت‪ .‬وبإعــان احلكــم عليهمــا‬\n‫قــرر املدعــى عليــه وكالــة قناعتــه باحلكــم وقــررت املدعيــة اعتراضهــا‬\n‫واســتعدت بتقــدمي الئحــة وجــرى تســليمها نســخة مــن احلكــم وافهمتهــا‬\n‫بــأن لهــا احلــق يف تقــدمي الئحتهــا خــال ثالثــن يومــا مــن تاريــخ هــذا‬\n‫اليــوم وانهــا اذا لــم تتقــدم بالئحتهــا خــال هــذه املــدة ســقط حقهــا يف‬\n‫االســتئناف واكتســب احلكــم القطعيــة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/04‬هـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ‬\n\n\n                                                                                      ‫‪234‬‬\n\f      ‫فقــد جــرى م ّنــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة اخلامســة‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع علــى هــذا‬\n      ‫احلكــم الصــادر مــن فضيلــة الشــيخ ‪ ......... /‬القاضــي يف احملكمــة‬\n      ‫العامــة جــدة املســجل بعــدد ‪ 34204578‬وتاريــخ ‪1434/5/4‬ه ـ املتضمــن‬\n      ‫دعــوى ‪......... /‬ضــد ورثــة ‪.........‬احملكــوم في ــه مبــا دون باطــن الصــك ‪،‬‬\n      ‫وبدراســة احلكــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقــرر املوافقــة‬\n      ‫علــى احلكــم بصــرف النظــر لعــدم االختصــاص ‪ .‬وبــاهلل التوفيــق ‪،‬‬\n                      ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪235‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":231,"source_page_end":235,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8edbcce07778626c240c52127a36b854f1cd97f78f38d03835207940b5f9eda9","normalized_text_hash":"41f022e0b60392d591a52a566057d0be6976dbee76cf62a0f0127a751b0d058b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p231-34204578"},{"id":"067b0ce3-ecfc-568f-b29f-fcd63fa798e2","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -عدم اختصاص المحكمة العامة بنظر الدعوى بدون االدعاء اخلاص -اختصاص المحكمة اجلزائية بذلك -قتل شبه عمد -حادث مروري -صرف نظر .","document_number":"34363986","case_number":"34251247","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنظر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/19","year":"1434","subject":"اختصاص -عدم اختصاص المحكمة العامة بنظر الدعوى بدون االدعاء اخلاص -اختصاص المحكمة اجلزائية بذلك -قتل شبه عمد -حادث مروري -صرف نظر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34363986 :‬تاريخه‪1434/11/19 :‬هـ‬\n                    ‫رقم الدعوى‪34251247 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34391228‬تاريخه‪1434/12/29 :‬هـ‬\n\n\n ‫اختصــاص ‪ -‬عــدم اختصــاص احملكمــة العامــة بنظــر الدعــوى بــدون‬\n ‫االدعــاء اخلــاص ‪ -‬اختصــاص احملكمــة اجلزائيــة بذلــك ‪ -‬قتــل شــبه‬\n                                   ‫عمــد ‪ -‬حــادث مــروري ‪ -‬صــرف نظــر ‪.‬‬\n\n\n\n\n                               ‫‪ -1‬املادة( ‪ ) 5‬من نظام االجراءات اجلزائية ‪.‬‬\n                             ‫‪ -2‬املادة ( ‪ ) 16‬من نظام االجراءات اجلزائية‪.‬‬\n                            ‫‪ -3‬املادة ( ‪ ) 129‬من نظام االجراءات اجلزائية‪.‬‬\n                            ‫‪ -4‬املادة ( ‪ ) 152‬من نظام االجراءات اجلزائية‪.‬‬\n\n\n\n ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بالقتل شــبه العمد‬\n ‫للمجنــي عليــه وذلــك لتعمــده الســير بالســيارة واملجنــي عليــه متعلــق بهــا‬\n ‫ممــا أدى إلــى ســقوطه ووفاتــه ‪ ،‬وطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n ‫واحلكــم عليــه مبــا نصــت بــه اإلرادة امللكيــة بحــق قاتلــي شــبه العمــد‬\n ‫وفق ـ ًا لقــرار مجلــس القضــاء األعلــى بهيئتــه الدائمــة رقــم (‪)3/106‬‬\n ‫وتاريــخ ‪1408/4/23‬ه ـ املؤيــد باألمــر الســامي رقــم (‪ )4/1197‬وتاريــخ‬\n ‫‪1409/6/12‬ه ـ باإلضافــة إلــى النظــر يف احلــق اخلــاص وجــرى إحالــة‬\n ‫القضيــة لدائــرة مشــكلة مــن ثالثــة قضــاة كاملتبــع يف احملكمــة‬\n\n                                                                                     ‫‪236‬‬\n\f      ‫العامــة ‪ -‬لــم يحضــر أحــد مطالبــا باحلــق اخلــاص ‪ -‬جــرى إعــادة القضيــة‬\n      ‫لالدعــاء العــام ألجلــه لعــدم اختصــاص احملكمــة العامــة بالنظــر واحلــال‬\n      ‫هــذه ‪ -‬عــادت القضيــة رفــق خطــاب مــن الشــرطة بأنــه جــرى إفهــام‬\n      ‫املدعــي اخلــاص بأنــه إن تــرك دعــواه تــرك فاســتعد باحلضــور إال أنــه لــم‬\n      ‫يحضــر ‪ -‬عليــه وألن احملكمــة ال تكلــف بإحضــار املدعي اخلاص وبناء‬\n      ‫علــى املــادة الثانيــة واخلمســن بعــد املائــة مــن نظــام االجــراءات اجلزائيــة‬\n      ‫املتضمنــة بــأن تــرك املدعــي باحلــق اخلــاص لدعــواه ال يكــون لــه تأثيــر‬\n      ‫علــى الدعــوى اجلزائيــة العامــة ‪ ،‬وبالتالــي فيكــون نظــر احلــق العــام‬\n      ‫أمــام احملكمــة املختصــة حســب املــادة السادســة عشــرة مــن النظــام‬\n      ‫املشــار إليــه ومبــا أن إثبــات اإلدانــة واحلكــم وفــق طلــب املدعــي العــام‬\n      ‫خــارج اختصــاص القضــاء املشــترك حســب املــادة التاســعة والعشــرين‬\n      ‫بعــد املائــة وبعــد إفهــام املدعــي العــام مبضمــون ذلــك طلــب احلكــم يف‬\n      ‫القضيــة حســب املــادة اخلامســة مــن النظــام املشــار إليــه‪ ،‬عليــه واســتناد ًا‬\n      ‫ملــا ســبق إيــراده ومبــا أن االختصــاص مــن املســائل األوليــة التــي يتوجــب‬\n      ‫النظــر فيهــا ولــو لــم يطلــب ذلــك أحــد مــن اخلصــوم ومبــا أن بقــاء القضيــة‬\n      ‫طــوال هــذه الفتــرة دون حكــم يلحــق ضــررا ًباملدعــى عليــه يف ظــل عــدم‬\n      ‫مطالبــة صاحــب الصفــة يف احلــق اخلــاص لــذا قــررت الدائــرة صــرف‬\n      ‫النظــر لعــدم االختصــاص وبــه حكمــت ألجــل احلــق العــام ‪ -‬قــرر املدعــي‬\n      ‫العــام عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة ‪-‬‬\n                                          ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪237‬‬\n\f‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة باحملكمــة العامــة بخميــس‬\n‫مشــيط واملشــتركون يف نظــر هــذه القضيــة الشــيخ ‪...........‬والشــيخ‬\n‫‪......................‬وبنــاء علــى املعاملــة احملالة لنا من فضيلة رئيس احملكمة‬\n‫العامــة بخميــس مشــيط برقــم ‪ 34251247‬وتاريــخ ‪1434/06/03‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341324717‬وتاريــخ ‪1434/06/03‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق ‪1434/11/19‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n‫‪ 11 :‬وفيهــا حضــر املدعــي العــام بخطــاب تعميــده مــن مرجعــه رقــم‬\n‫‪ ...........‬يف ‪1434/1/28‬ه ـ ولــم يحضــر املدعــى باحلــق اخلــاص وكذلــك‬\n‫لــم يحضــر املدعــى عليــه ومبناقشــة املدعــي العــام عــن الدعــوى أجــاب‬\n‫تنحصــر الدعــوى يف اآلتــي‪ :‬أدعــي علــى ‪ ،...........‬البالــغ مــن العمــر (‪)47‬‬\n‫عامـ ًا مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ )...........‬متعلــم‪،‬‬\n‫صيدلــي ‪ ،‬يقيــم مبحافظــة خميــس مشــيط ‪ ،‬املقبــوض عليــه بتاريــخ‬\n‫‪1433/6/10‬ه ـ واملفــرج عنــه بتاريــخ ‪1433/6/11‬ه ـ واملعــاد توقيفــه‬\n‫بتاريــخ ‪1433/9/19‬ه ـ واملفــرج عنــه بتاريــخ ‪1433/12/19‬ه ـ مبوجــب‬\n‫قــرار جلنــة إدارة الهيئــة رقــم (‪ )...........‬لعــام ‪1433‬ه ـ ‪.‬فإنــه بتاريــخ‬\n‫‪1433/6/10‬ه ـ تقــدم حملافظــة خميــس مشــيط املواطــن ‪........... /‬‬\n‫بدعــوى تتضمــن قيــام شــخص باملشــادة مــع أخيــه املجنــي عليــه ‪........... /‬‬\n‫وأن هــذا الشــخص قــام مبــد يــده علــى أخيــه وأراد الهــروب مــن الشــارع‬\n‫فقــام أخيــه ومتســك بالســيارة وركــب علــى الكبــوت فقــام الشــخص‬\n‫املدعــى عليــه بأخــذه والســير بالســيارة بســرعة جنونيــة وأســقطه‬\n‫أرض ـ ًا ومت إســعاف أخيــه ونقلــه إلــى املستشــفى وقــد تــويف مســاء يــوم‬\n\n                                                                                    ‫‪238‬‬\n\f      ‫أن هنــاك مقيــم يدعــى ‪........... /‬يعــرف اجلاني‬  ‫‪1433/6/6‬ه ـ كمــا أفــاد َّ‬\n      ‫حيــث أبلغــه أن املتهــم ســحب أخيــه مســافة يف الشــارع بعــد أن حصــل‬\n      ‫بينهــم مشــادة كالميــة عنــد املشــغل الــذي تعمــل بــه زوجتــه واملقابــل‬\n      ‫ملنــزل املجنــي عليــه وذلــك حســب مــا نقلــه لــه ‪...........‬مــن كالم مــن‬\n      ‫زوجتــه ‪ .‬وباســتجواب املتهــم ‪ /‬أفــاد أنــه قــام بإيصــال زوجتــه إلــى املشــغل‬\n      ‫الــذي تعمــل بــه صديقتهــا ‪ ........‬وأثنــاء وقــوف زوجتــه عنــد بــاب املشــغل‬\n      ‫تهجــم عليهــا شــخص يلبــس ثــوب أبيــض وقــام مبالحقتهــا حتــى ركبــت‬\n      ‫يف الســيارة وأغلقــت البــاب فقــام هــذا الشــخص بالصعــود فــوق كبــوت‬\n      ‫ســيارته ورفــض النــزول فتحــرك بالســيارة بســرعة منخفضــة جــد ًا بحثـ ًا‬\n      ‫عــن ســيارة شــرطة حيــث كان يشــاهد الشــرطة دائم ـ ًا عنــد البنــك‬\n      ‫يف أول الشــارع وحــن وصــل إلــى نهايــة الشــارع واقتــرب مــن الشــارع‬\n      ‫الرئيســي وقبــل اخلــروج مــن احلــارة قفــز املجنــي عليــه مبحــض إرادتــه ثــم‬\n      ‫رآه ســاقط ًا ويحــاول أن يقــوم كمــا أنــه لــم يتصــل علــى الشــرطة ألنــه‬\n      ‫أراد ســتر املوضــوع الن املجنــي عليــه اعتــدى علــى شــرفه ثــم انــه ال يريــد‬\n                             ‫منــه شــيء وقــد رآه واقف ـ ًا بعــد أن قفــز مــن الســيارة ‪.‬‬\n      ‫كمــا أقـ َّـر بأنــه حتــرك بســيارته واملجنــي عليــه متعلــق بهــا فــوق‬\n      ‫الكبــوت واســتمر يف املشــي مســافة طويلــة حتــى قفــز املجنــي عليــه‬\n      ‫مــن فــوق الســيارة كمــا قــال أن وجــود املجنــي عليــه يف مــكان بعيــد‬\n      ‫عــن املــكان الــذي قفــز فيــه مــن الســيارة فيــه دليــل علــى أن املجنــي‬\n      ‫عليــه ســليم ومعافــى بعــد الســقوط وقــد يكــون تعــرض إلصابــة أخــرى‬\n      ‫كمــا أفــاد أنــه يعتقــد أن املجنــي عليــه كان ســكران ًا ويريــد البحــث‬\n      ‫عــن ســلوكه وســوابقه ‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n      ‫للمدعــى عليــه ‪ ........... /‬بالقتــل شــبه العمــد للمجنــي عليــه ‪...........‬‬\n\n\n‫‪239‬‬\n\f‫وذلــك لتعمــده الســير بالســيارة واملجنــي عليــه متعلــق بهــا ممــا أدى إلــى‬\n‫ســقوطه ووفاتــه وبالبحــث عــن ســوابق املتهــم اتضــح عــدم وجــود ســوابق‬\n‫مســجلة عليــه ‪ .‬وبالبحــث عــن ســوابق املجنــي عليــه وســلوكه اتضــح‬\n‫‪ :‬وجــود رقــم ســجني لديــه (‪ )...........‬حيــازة مخــدرات ولــم تســتكمل‬\n‫وألن مــا أقــدم عليــه املتهــم وهــو بكامــل‬‫إجــراءات تســجيل ســابقة ‪َّ .‬‬\n‫أهليتــه املعتبــرة شــرع ًا فعــل محـ َّـرم ومعاقــب عليــه شــرع ًا لــذا فإننــي‬\n‫أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا نصــت بــه اإلرادة‬\n‫امللكيــة بحــق قاتلــي شــبه العمــد وفق ـ ًا لقــرار مجلــس القضــاء األعلــى‬\n‫بهيئتــه الدائمــة رقــم (‪ )3/106‬وتاريــخ ‪1408/4/23‬ه ـ املؤيــد باألمــر‬\n‫الســامي رقــم (‪ )4/1197‬وتاريــخ ‪1409/6/12‬ه ـ باإلضافــة إلــى النظــر‬\n‫يف احلــق اخلــاص هــذه دعــواي بعــد ذلــك جــرى إفهامــه بتخلــف صاحــب‬\n‫احلــق اخلــاص عــن احلضــور وقــد جــرى منــا الكتابــة بذلــك لهيئــة التحقيــق‬\n‫واالدعــاء العــام باخلطــاب رقــم ‪ 34674627‬يف ‪1434/04/15‬ه ـ لعــدم‬\n‫املراجعــة مــن قبــل صاحــب احلــق اخلــاص وأعيــدت باخلطــاب رقــم ‪...........‬‬\n‫يف ‪1434/04/22‬ه ـ حيــث إنــه ال يكــون لتــرك املدعــي باحلــق اخلــاص‬\n‫لدعــواه تأثيــر علــى الدعــوى اجلزائيــة العامــة ثــم جــرت الكتابــة لهــم‬\n‫بهــذا اخلصــوص باخلطــاب رقــم ‪ 341001355‬يف ‪1434/4/30‬ه ـ حيــث‬\n‫ال ميكــن النظــر يف احلــق العــام فقــط كونــه خــارج اختصــاص القضــاء‬\n‫املشــترك ما لم يتقدم صاحب الصفة باحلق اخلاص باملطالبة بالقصاص‬\n‫حســب املــادة (‪ )129‬مــن نظــام اإلجــراءات اجلزائيــة ثــم أعيــدت إلينــا‬\n‫مؤخــر ًا بخطــاب مديــر مركــز شــرطة ‪ ...........‬رقــم ‪2013/1/6/602‬‬\n‫يف ‪1434/05/19‬ه ـ املتضمــن أنــه جــرى إحضــار املدعــي باحلــق اخلــاص‬\n‫واســتعد باحلضــور وأفهــم بأنــه مــن تــرك دعــواه تــرك حســب اإلقــرار‬\n\n\n                                                                                       ‫‪240‬‬\n\f      ‫املرفــق باخلطــاب (ا‪0‬هــ) ومنــذ ذلــك التاريــخ لــم يراجــع صاحــب احلــق‬\n      ‫اخلــاص ممــا يعنــي تركــه لدعــواه وال تكلــف احملكمــة بإحضــاره‬\n      ‫كونــه صاحــب الطلــب ومبــا أن املــادة الثانيــة واخلمســون بعــد املائــة‬\n      ‫تنــص علــى أن تــرك املدعــي باحلــق اخلــاص لدعــواه ال يكــون لــه‬\n      ‫تأثيــر علــى الدعــوى اجلزائيــة العامــة وبالتالــي فيكــون نظــر احلــق العــام‬\n      ‫أمــام احملكمــة املختصــة حســب املــادة السادســة عشــرة مــن النظــام‬\n      ‫املشــار إليــه ومبــا أن إثبــات اإلدانــة واحلكــم وفــق طلــب املدعــي العــام‬\n      ‫خــارج اختصــاص القضــاء املشــترك حســب املــادة التاســعة والعشــرون‬\n      ‫بعــد املائــة وبعــد إفهــام املدعــي العــام مبضمــون ذلــك طلــب احلكــم يف‬\n      ‫القضيــة حســب املــادة اخلامســة مــن النظــام املشــار إليــه ‪ ،‬عليــه واســتناد ًا‬\n      ‫ملــا ســبق إيــراده ومبــا أن االختصــاص مــن املســائل األوليــة التــي يتوجــب‬\n      ‫النظــر فيهــا ولــو لــم يطلــب ذلــك أحــد مــن اخلصــوم ومبــا أن بقــاء القضيــة‬\n      ‫طــوال هــذه الفتــرة دون حكــم يلحــق ضــرر ًا باملدعــى عليــه يف ظــل عــدم‬\n      ‫مطالبــة صاحــب الصفــة يف احلــق اخلــاص لــذا قررنــا صــرف النظــر لعــدم‬\n      ‫االختصــاص وبــه حكمنــا ألجــل احلــق العــام وبعرضــه علــى املدعــي العام‬\n      ‫قــرر عــدم القناعــة وطلــب رفــع احلكــم حملكمــة االســتئناف بــدون‬\n      ‫الئحــة فأجيــب لطلبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اخلماســية مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بخميــس مشــيط‬\n      ‫برقــم ‪ 341324717‬وتاريــخ ‪1434/11/25‬هـ ـ املرفــق بهــا القــرار‬\n      ‫الشــرعي الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪/‬‬\n\n\n‫‪241‬‬\n\f‫‪...........‬والشــيخ‪........... /‬والشــيخ‪........... /‬برقــم ‪ 34363986‬وتاريــخ‬\n‫‪1434/11/19‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ــد‪........... /‬مصــري‬\n‫اجلنســية) يف قضيــة (قتــل) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n‫حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪ ،‬وبدراســة‬\n‫القــرار الشــرعي وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                  ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪242‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":236,"source_page_end":242,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1ac8e48126e2b5615cb069112257bf7f7a9b604c625d65552885605aa07c1ea5","normalized_text_hash":"1605c5feadb9fe8b2ba60a201effabc6a8fbac1801a6076139b526b3c48342f3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p236-34363986"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

